                ExerciseItem(id: UUID(), prompt: "Каждый день с понедельника по субботу у вас по 1 часу логопедии, лечебной физкультуры и трудотерапии. Сколько часов терапии в неделю?", options: ["15 часов", "18 часов", "21 час", "24 часа"], correctAnswer: "18 часов", explanation: "3 часа в день умножаем на 6 дней и получаем 18 часов."),
